css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; inset: 0; margin: auto; clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%); }
.loader span:nth-child(1) { background: var(--accent); animation: spin-cw calc(var(--loader-speed) * 2.6) linear infinite; }
.loader span:nth-child(2) { inset: 22%; background: var(--accent-2); animation: spin-ccw calc(var(--loader-speed) * 2) linear infinite; }
.loader span:nth-child(3) { inset: 44%; background: color-mix(in srgb, #fff 35%, var(--accent)); animation: spin-cw calc(var(--loader-speed) * 1.4) linear infinite; }
@keyframes spin-cw { to { transform: rotate(360deg); } }
@keyframes spin-ccw { to { transform: rotate(-360deg); } }
